function canReach($dx, $dy, $x, $y) {
    // We need to find non-negative integers a, b, c, d such that:
    // (a + b - c - d) * x = dx
    // (a - b + c - d) * y = dy

    // Let's try all possible values of (a+b-c-d) and (a-b+c-d)
    // But that's infinite. Instead, let's use the constraints.

    // Case 1: x == 0 and y == 0
    // Then dx must be 0 and dy must be 0
