        return ($dx == 0 && $dy == 0);
    }

    // Case 2: x == 0, y != 0
    // Then dx must be 0
    // And (a - b + c - d) * y = dy
    // Let p = a - b, q = c - d
    // p - q = dy / y (must be integer)
    // |p| <= a+b, |q| <= c+d, with parity constraints
    // Since x=0, the first equation is 0=dx, so dx must be 0.
