        // Let s = a - b + c - d
        // s * y = dy
        if ($dy % $y != 0) return false;
        $s = $dy / $y;
        // We need to find non-negative a, b, c, d such that a - b + c - d = s
        // This is always possible for any integer s.
        // For example, if s >= 0, set a = s, b = 0, c = 0, d = 0
        // If s < 0, set a = 0, b = -s, c = 0, d = 0
        return true;
    }

    // Case 3: x != 0, y == 0
    // Then dy must be 0
    // And (a + b - c - d) * x = dx
    if ($y == 0) {
        if ($dy != 0) return false;
        if ($dx % $x != 0) return false;
        $s = $dx / $x;
        // We need a + b - c - d = s
