    // (a - b + c - d) * y = dy  =>  a - b + c - d = dy / y (must be integer)

    if ($dx % $x != 0 || $dy % $y != 0) return false;

    $m = $dx / $x;  // a + b - c - d = m
    $n = $dy / $y;  // a - b + c - d = n

    // Let u = a + b, v = c + d
    // Then u - v = m
    // And let p = a - b, q = c - d
    // Then p - q = n

    // From u - v = m: v = u - m
    // Since u >= 0 and v >= 0, we need u >= max(0, m) and u - m >= 0, so u >= m if m > 0, or u >= 0 if m <= 0
    // Actually v = u - m >= 0 => u >= m
    // And u >= 0
    // So u >= max(0, m)

    // Also |p| <= u and p ≡ u (mod 2)
    // |q| <= v and q ≡ v (mod 2)
    // p - q = n

