    // v = u - m >= 0
    // There exist p, q with |p| <= u, |q| <= v, p ≡ u (mod 2), q ≡ v (mod 2), and p - q = n

    // This is a bounded search. Note that m and n are bounded since dx, dy are bounded by 2*10^5 and x, y >= 1.
    // So |m| <= 2*10^5, |n| <= 2*10^5

    // We can try values of u in a reasonable range.
    // The minimum u is max(0, m). What's a good upper bound?
    // We need |p| <= u and |q| <= v = u - m, and p - q = n.
    // The maximum possible |p - q| is u + (u - m) = 2u - m (if m <= 0) or u + u - m = 2u - m
    // Actually max |p - q| = u + v = u + (u - m) = 2u - m
    // We need |n| <= 2u - m, so u >= (|n| + m) / 2 if m > 0, or u >= |n|/2 + m/2... 
    // Let's just try u from max(0, m) to some upper bound.

    // Upper bound: we need 2u - m >= |n|, so u >= (|n| + m) / 2
    // Also u must have the same parity as p, and v = u - m must have the same parity as q.
    // p ≡ u (mod 2), q ≡ v (mod 2) = (u - m) (mod 2)
    // p - q = n
    // p ≡ u (mod 2), q ≡ u - m (mod 2)
    // So p - q ≡ u - (u - m) = m (mod 2)
    // Therefore n ≡ m (mod 2) is necessary.

    if (($n - $m) % 2 != 0) return false;

    // Now we need to find u >= max(0, m) such that:
    // v = u - m >= 0
    // There exist p with |p| <= u, p ≡ u (mod 2), and q = p - n with |q| <= v, q ≡ v (mod 2)

