    // The upper bound can be max(0, m) + |n| + 2 or so.

    $minU = max(0, $m);
    $maxU = $minU + abs($n) + 2;

    for ($u = $minU; $u <= $maxU; $u++) {
        $v = $u - $m;
        if ($v < 0) continue;

        // Check parity: p ≡ u (mod 2), q ≡ v (mod 2)
        // p - q = n
        // p ≡ u (mod 2), q ≡ v (mod 2)
        // So n = p - q ≡ u - v (mod 2) = u - (u - m) = m (mod 2)
        // We already checked n ≡ m (mod 2)

        // Now we need to find p such that:
        // |p| <= u
        // p ≡ u (mod 2)
        // q = p - n
        // |q| <= v
        // q ≡ v (mod 2)

        // q ≡ v (mod 2) means p - n ≡ v (mod 2), so p ≡ n + v (mod 2)
        // But we also need p ≡ u (mod 2)
        // So we need n + v ≡ u (mod 2)
        // n + (u - m) ≡ u (mod 2)
        // n - m ≡ 0 (mod 2)
        // Which we already checked.

